data = cells('Sheet0', 'B4:K42')
max_abs_change = -1
best_category = ''
for row in data:
    cat_name = row[1]
    if not cat_name or cat_name == 'All items':
        continue
    try:
        pct_change_str = row[7] # Column H is Unadjusted percent change Sep. 2024-Oct. 2024
        if pct_change_str is None or pct_change_str == '':
            continue
        pct_change = float(pct_change_str)
        abs_change = abs(pct_change)
        if abs_change > max_abs_change:
            max_abs_change = abs_change
            best_category = cat_name
    except (ValueError, TypeError):
        continue
result = best_category
